    menuMusic.pause();battleMusic.currentTime=0;const battlePlayback=menuMusicEnabled?battleMusic.play():null;if(battlePlayback&&typeof battlePlayback.catch==="function")battlePlayback.catch(()=>{});duel=null;saveDuel();
