  function renderZones(){return [["local","LOCAL","⌂"],["terrain","TERRENO","▱"],["climate","CLIMA","◌"]].map(([key,label,glyph])=>{const cardId=duel.sharedZones&&duel.sharedZones[key],card=cardId&&cardById[cardId];if(!card)return '<div class="battle-zone" data-drop-zone="'+key+'" aria-label="'+label+': vazio. Solte aqui a carta correspondente"><small>'+label+'</small><span class="zone-glyph">'+glyph+'</span><b>Vazio</b></div>';const art=card.art?'<img src="'+card.art+'" alt="">':'<span>'+escapeHTML(card.symbol)+'</span>';return '<div class="battle-zone occupied" role="button" tabindex="0" data-zone-card="'+cardId+'" aria-label="Ampliar carta '+escapeHTML(card.name)+' em '+label+'"><article class="zone-card-mini" style="--card-glow:'+card.glow+'" title="'+escapeHTML(card.name)+'"><header><span>'+escapeHTML(card.faction.toLocaleUpperCase("pt-BR"))+'</span><b>'+escapeHTML(card.symbol)+'</b></header><div class="zone-card-mini-art">'+art+'</div><strong>'+escapeHTML(card.name)+'</strong><small>'+escapeHTML(card.type.toLocaleUpperCase("pt-BR"))+'</small></article></div>';}).join("");}
